script:
var comp = app.project.items.addComp("Claude bridge test", 540, 540, 1, 3, 25);
var bg = comp.layers.addSolid([0.08, 0.09, 0.12], "Background", 540, 540, 1);
var t = comp.layers.addText("Claude Bridge");
var doc = t.property("ADBE Text Properties").property("ADBE Text Document");
var td = doc.value; td.fontSize = 56; td.fillColor = [1, 0.85, 0.2]; td.justification = ParagraphJustification.CENTER_JUSTIFY; doc.setValue(td);
t.property("ADBE Transform Group").property("ADBE Position").setValue([270, 290]);
var op = t.property("ADBE Transform Group").property("ADBE Opacity");
op.setValueAtTime(0, 0); op.setValueAtTime(1, 100);
t.property("ADBE Effect Parade").addProperty("ADBE Drop Shadow");
comp.time = 1.5;
comp.openInViewer();
log("built", comp.name, comp.id);
return { id: comp.id, layers: comp.numLayers };
